<script lang="ts">
  import { t, caption, locale } from '../i18n';
  import { runtime as TD } from '../runtime';
  import { liveValue } from './live-value';
  export interface Model {
    type: string; key: string; id: string; label: string; value: string | number; hint?: string;
    unit?: string; min: string | number; max: string | number; step: string | number;
    options: [string, string][]; checked: boolean; italic: boolean; px: number; range: string | number;
    radioLabel: string; radios: { key: string; label: string; path: string; on: boolean; disabled: boolean }[];
    colour: { none: boolean; nullable: boolean; fills: boolean; label: string; css: string };
    preview: string; previewName: string;
  }
  let { model }: { model: Model } = $props();
  const grouped = $derived(['bi', 'align', 'valign', 'icons'].includes(model.type));
</script>
<div class="row">{#if grouped}<span class="field-label" id={model.id + '-label'}>{caption(model.label, $locale)}</span>{:else}<label for={model.id}>{caption(model.label, $locale)}</label>{/if}<div class="ctl" role={model.type === 'bi' ? 'group' : undefined} aria-labelledby={model.type === 'bi' ? model.id + '-label' : undefined}>{#if model.type === 'textarea'}<textarea id={model.id} data-key={model.key} data-tx="text" placeholder={t("ui.text.math", "Text, $math$", {}, $locale)} {@attach liveValue(model.value)}></textarea>{:else if model.type === 'text'}<input type="text" id={model.id} data-key={model.key} data-tx={model.key === 'lbl' ? 'math' : 'text'} placeholder={model.key === 'lbl' ? t('form.tx.math', 'Maths, without $', {}, $locale) : t('form.tx.text', 'Text, $math$', {}, $locale)} {@attach liveValue(model.value)}>{:else if model.type === 'number'}<input type="number" id={model.id} data-key={model.key} {@attach liveValue(model.value)} min={model.min} step={model.step}>{#if model.unit}<span class="val">{model.unit}</span>{/if}{:else if model.type === 'range'}<input type="range" id={model.id} data-key={model.key} min={model.min} max={model.max} step={model.step} {@attach liveValue(model.value)}><span class="val">{model.range}</span>{:else if model.type === 'select' || model.type === 'size'}<select id={model.id} data-key={model.key} {@attach liveValue(model.value)}>{#each model.options as [value, label]}<option {value} style:font-family={model.key === 'font' ? TD.FONTS.find((font: string[]) => font[0] === value)?.[2] : undefined}>{caption(label, $locale)}</option>{/each}</select>{#if model.type === 'size'}<input type="number" class="px" data-sizepx="1" min="2" max="200" step="1" {@attach liveValue(model.px)} title={t("ui.size.in.px.type.a.value.and.press.enter", "Size in px — type a value and press Enter", {}, $locale)}>{/if}{:else if model.type === 'bi'}<label class="chk"><input type="checkbox" data-key="bold" checked={model.checked}><b>{t("ui.bold", "Bold", {}, $locale)}</b></label><label class="chk"><input type="checkbox" data-key="italic" checked={model.italic}><i>{t("ui.italic", "Italic", {}, $locale)}</i></label>{:else if model.type === 'checkbox'}<input type="checkbox" id={model.id} data-key={model.key} checked={model.checked}>{:else if model.type === 'align' || model.type === 'valign' || model.type === 'icons'}<div class={model.type === 'icons' ? 'seg-ctl fill' : 'seg-ctl'} role="radiogroup" aria-label={caption(model.radioLabel, $locale)}>{#each model.radios as radio}<button type="button" role="radio" data-alignv={model.type === 'align' ? radio.key : undefined} data-valign={model.type === 'valign' ? radio.key : undefined} data-pk={model.type === 'icons' ? model.key : undefined} data-pv={model.type === 'icons' ? radio.key : undefined} class={radio.on ? 'on' : ''} aria-checked={radio.on} disabled={radio.disabled} title={caption(radio.label, $locale)}><svg viewBox="0 0 20 20"><path d={radio.path}/></svg></button>{/each}</div>{:else if model.type === 'color'}<button id={model.id} type="button" class={'cbtn' + (model.colour.none ? ' none' : '')} data-color={model.key} data-nullable={model.colour.nullable ? '1' : undefined} data-fills={model.colour.fills ? '1' : undefined} title={caption(model.colour.label, $locale)}><span style:background={model.colour.css}></span></button><span class="cval">{caption(model.colour.label, $locale)}</span>{:else if model.type === 'width'}<input type="number" id={model.id} data-key={model.key} {@attach liveValue(model.value)} min="0.25" step="0.25"><button type="button" class="ddbtn" data-dd={model.key} title={t("ui.line.width.presets", "Line width presets", {}, $locale)}><svg viewBox="0 0 10 10"><path d="M2 3.5l3 3 3-3"/></svg></button><span class="val">{t("ui.px", "px", {}, $locale)}</span>{:else}<button type="button" class="ddsel" id={model.id} data-dd={model.key} title={model.type === 'dash' ? t('style.dashPattern', 'Dash pattern', {}, $locale) : model.type === 'shaft' ? t('style.shaft', 'Shaft', {}, $locale) : caption(model.label, $locale)}>{@html model.preview}<span>{caption(model.previewName, $locale)}</span><svg class="chev" viewBox="0 0 10 10"><path d="M2 3.5l3 3 3-3"/></svg></button>{/if}</div></div>{#if model.hint}<div class="hint">{caption(model.hint, $locale)}</div>{/if}
